    "question": "How can analysis become something people actually use?",
    "is_question": true,
    "form": "Rafael’s analysis memo: The question → The data → What I did → What I found → What I would do.",
    "object": "One seven-leaf memo, with five section leaves and two evidence leaves, that persists and rearranges throughout the scroll.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The memo uses Rafael’s confirmed working sequence and connects his particular tracking dashboard, reporting script and public rent map to their distinct evidence."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The leaves carry project scope and outcomes, with rearrangements explicitly pairing contributions and evidence rather than merely decorating the text."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence moves from a question through context, method and contributions to supporting evidence and an answer."
    },
    "clipart": {
      "result": "pass",
      "reason": "The memo is a confirmed working document organised around his own fields, rather than a stock emblem of analytics."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan preserves corrected project scopes, attribution and approximate figures while excluding inflated titles and confidential artifacts."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening provides his name, role, plain-language positioning, Rent Map usage proof and immediate contact navigation."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question and dashboard line are understandable outside analytics and supported by credible, accurately scoped work."
    }
  },
